#!/usr/bin/env node
/**
 * Writes the Targets console's copy of the Growth Calculator formulas from the
 * server's `growthCalculation.formula.ts`.
 *
 * Why a generated file rather than an import: the server is the authority (it
 * recalculates every save) and imports no `@duncit/*` package by design (rule
 * 40), while the console needs the same formulas in the browser to recalculate
 * as the planner types. Keeping two hand-written copies is exactly the kind of
 * clone the duplication gate exists to stop — and two copies can drift apart,
 * so a preview could promise a figure the saved record does not hold. Same
 * arrangement as `generate-wa-events.mjs`, in the other direction.
 *
 * Run `node scripts/generate-growth-formula.mjs` after editing the formulas;
 * `--check` fails instead of writing, which is what CI runs so a stale copy
 * cannot ship.
 */
import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const SOURCE = join(ROOT, "server/src/modules/targets/growthCalculation/growthCalculation.formula.ts");
const OUT = join(ROOT, "portals/targets/src/lib/generated/growth-formula.ts");
const NAME = "generate-growth-formula";
const check = process.argv.includes("--check");

const source = readFileSync(SOURCE, "utf8").replaceAll("\r\n", "\n");
// The copy must stand alone in the browser bundle: one import would pull a
// server module (or a path the console's Docker image never copies) into it.
if (/^\s*import\s/m.test(source)) {
  console.error(`${NAME}: ${SOURCE} has an import — the formula file must import nothing`);
  process.exit(1);
}
const headerEnd = source.indexOf("*/\n");
if (!source.startsWith("/**") || headerEnd === -1) {
  console.error(`${NAME}: ${SOURCE} no longer opens with a doc comment — update this script`);
  process.exit(1);
}
const body = source.slice(headerEnd + 3).replace(/^\n+/, "");

const file = `/**
 * GENERATED by \`node scripts/generate-growth-formula.mjs\` from
 * \`server/src/modules/targets/growthCalculation/growthCalculation.formula.ts\`
 * — do not edit; change the server file and regenerate.
 *
 * The console recalculates with this copy as the planner types; the server
 * recalculates with the original on every save. CI fails if the two differ.
 */

${body}`;

if (check) {
  let current = "";
  try {
    current = readFileSync(OUT, "utf8").replaceAll("\r\n", "\n");
  } catch {
    console.error(`${NAME}: ${OUT} is missing — run the script without --check`);
    process.exit(1);
  }
  if (current !== file) {
    console.error(
      `${NAME}: growth-formula.ts is out of date with the server formulas.\n` +
        "Run `node scripts/generate-growth-formula.mjs` and commit the result.",
    );
    process.exit(1);
  }
  console.log(`${NAME}: growth-formula.ts matches the server formulas`);
} else {
  mkdirSync(dirname(OUT), { recursive: true });
  writeFileSync(OUT, file, "utf8");
  console.log(`${NAME}: wrote ${OUT.slice(ROOT.length + 1)}`);
}
